def floor_nth_root(n, k):
    if k <= 0:
        return 0
    if n < 1:
        return 0
    lo, hi = 1, 1
    # increase hi until hi^k > n
    while pow(hi, k) <= n:
        hi *= 2
    hi -= 1
    # binary search in [lo, hi]
    best = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        val = pow(mid, k)
        if val <= n:
            best = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return best

def ceil_nth_root(n, k):
    if k <= 0:
        return 0
    if n <= 1:
        return 1
    f = floor_nth_root(n, k)
    if pow(f, k) == n:
        return f
    return f + 1

